from review import card,save,DATE

def b(t,s,r=None):
 d=dict(title=t,text=s)
 if r:d['citation']=r
 return d
def sm(s,r):return dict(sentences=s,basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=r)
def imp(c,s):return dict(score=c['importance']['score'],method='editorial',reason=s+' Existing numerical score retained.',assessed_on=DATE)

i='TCS-2502';_,c=card(i);refs=c['references'];refs[0]['locator']='COLT 2023, Section 2.2, page 10: asks to characterize the canonical equality-constrained SoS formulation. The nearby low-degree-polynomial refutation conjecture is a different model; the paper states no formal implication between the two frameworks.'
refs.extend([dict(id='coloring2021',title='A Stress-Free Sum-Of-Squares Lower Bound for Coloring',authors='Pravesh K. Kothari, Peter Manohar',year=2021,url='https://arxiv.org/abs/2105.07517',locator='Sections 1.1 and 1.5, arXiv v1: weak and strong coloring axioms, higher-degree lower bound for the weak formulation, and exact-equality obstacle read.'),dict(id='coloring2025',title='Sum-of-Squares Lower Bounds for Coloring Random Graphs',authors='Aaron Potechin, Jeff Xu',year=2025,url='https://doi.org/10.1145/3717823.3718151',locator='STOC 2025, pages 84–95. Publisher abstract and official proceedings abstract checked: for every fixed ε>0, the canonical SoS formulation needs Ω(log n) degree to certify chromatic number at least n^{1/2+ε}; the construction respects exact equality constraints.'),dict(id='coloring_thesis2025',title='Spectral Techniques for Average-Case Complexity',authors='Jeff Xu',year=2025,url='https://csd-web-01.andrew.cmu.edu/sites/default/files/phd-thesis/CMU-CS-25-137.pdf',locator='Chapter 8: Definition 8.1.1 and Sections 8.1–8.2 read. Supplies the exact-coloring model and discussion of the advance beyond degree two. The displayed fine-parameter inequality in Theorem 8.1.2 has an apparent direction inconsistency; no fine-window bound is inferred from it.')])
issue='The 2023 passage asks broadly to “characterize” this relaxation without fixing a degree regime or the precision of the color threshold. The main higher-degree equality-constraint barrier has since been established at q=n^{1/2+ε} for every fixed ε>0. The source does not identify a specific remaining question about subpolynomial factors or a sharper degree/color tradeoff. Such a residual target must be justified before this is certified as a precise open benchmark; the old broad request must not be silently replaced by an invented finer conjecture.'
save(i,dict(title='Canonical SoS thresholds for random-graph colorability',formal='Characterize when the equality-constrained sum-of-squares relaxation can refute q-colorability of G∼G(n,1/2), as a function of the number q of colors and the SoS degree D. The source raised this question near the √n color scale, where lower bounds had been proved for a weaker inequality formulation. A 2025 theorem now establishes a higher-degree lower bound for the canonical formulation; the source does not specify the precision of any remaining threshold question.',definitions='G(n,1/2) is the distribution on simple labeled graphs with vertex set {1,…,n}, with each unordered pair independently made an edge with probability 1/2. A proper q-coloring assigns each vertex one label in {1,…,q}, with adjacent vertices receiving different labels. Use real variables x_{v,c} as color indicators and equations x_{v,c}²−x_{v,c}=0, x_{u,c}x_{v,c}=0 for every edge {u,v}, and Σ_c x_{v,c}−1=0. The 2021 strong formulation also explicitly includes x_{v,c}x_{v,c′}=0 for c≠c′. For a specified set of polynomial equations h=0 and integer D≥2, its degree-D pseudoexpectation is a linear map L from real polynomials of total degree at most D to ℝ with L(1)=1, L(p²)≥0 whenever 2 deg p≤D, and L(ph)=0 for every equation and multiplier with deg(ph)≤D. Feasibility means such an L exists, so this relaxation cannot refute colorability. The weak formulation instead uses Σ_c x_{v,c}≥1 and its SoS inequality conditions, allowing multiple colors at a vertex in the underlying Boolean constraints. Probability statements are over G and high probability means probability tending to one as n→∞. D counts polynomial degree, not running-time exponent or the number of variables.',question_type='asymptotic_complexity',answer_criterion='A completed residual formulation must specify the precise axiom presentation, the allowed D and q regimes, the success probability and the requested asymptotic precision, then seek matching feasibility and refutation bounds at that precision. Merely proving a higher-degree lower bound at q=n^{1/2+ε} is already covered by the 2025 result and cannot count as resolving a new open question.',context_blocks=[b('Why the equality matters','At the level of actual colorings, both formulations describe colorability. At low SoS degree, however, enforcing exact polynomial equalities can make the relaxation stronger than merely requiring at least one color per vertex.', 'coloring2021'),b('The original gap concerned the stronger relaxation','The 2021 lower bound treated the inequality formulation. The 2023 paper explicitly singled out the canonical equality formulation as an unresolved issue, separately from its own low-degree-polynomial model.', 'primary'),b('Substantial progress closes the old higher-degree obstacle','Potechin and Xu prove that, for every fixed ε>0, degree Ω(log n) is required to certify a chromatic lower bound of n^{1/2+ε}. The official proceedings abstract explicitly says that the pseudoexpectations respect exact equality constraints.', 'coloring2025'),b('What the checked theorem does not specify here','A guarantee for each fixed positive ε is not automatically a guarantee for every sequence q/√n→∞. The historical passage supplies no exact demand concerning such a finer window.', 'primary'),b('Remaining formulation issue',issue)],why='Measures how much exact combinatorial constraints strengthen semidefinite proof systems on random instances, a central source of evidence about average-case computational barriers.',references=refs,progress=[dict(date='2021',text='Higher-degree lower bounds are proved for the weak coloring axioms; handling the strong equality formulation remains an obstacle.',citation='coloring2021'),dict(date='2023',text='The source asks to characterize the canonical equality-constrained relaxation.',citation='primary'),dict(date='2025-06-15',text='The published STOC result establishes the Ω(log n) degree barrier for every fixed color exponent 1/2+ε, including exact equality constraints.',citation='coloring2025')],status='uncertain',status_note='The old extraction is no longer a reliable open statement: published 2025 work answers its main higher-degree obstacle. The checked sources do not pin down a separate, precise residual threshold claim. Retained as an improved but unfinished formulation, without asserting that the established 2025 lower bound remains open.',model_self_contained=False,requires_context=True,statement_review=dict(reviewed_on=DATE,status='needs_specification',remaining_issue=issue,notes=['Recovered the √n scale, exact-coloring axioms and SoS model, and recorded the published 2025 advance.']),importance=imp(c,'A foundational average-case lower-bound question about the effect of exact constraints in sum-of-squares relaxations.'),review_note='Repaired the corrupted square root and restored the actual SoS question. Checked the 2025 theorem and its exact-equality scope. Did not invent a fine-window problem from a historical request to characterize the relaxation.',working_summary=sm(['The source asks when sum-of-squares can rule out q-colorings of a dense random graph.','The key distinction is between at-least-one-color inequalities and exact-coloring equalities.','A 2021 lower bound applied to the weaker formulation near the square-root color scale.','Published 2025 work establishes the higher-degree barrier for the canonical model at every fixed color exponent above one half.','A precise remaining threshold question has not been specified by the historical passage.'],['primary','coloring2021','coloring2025','coloring_thesis2025'])),notes=['Restored the √n scale and equality-constrained SoS target.','Defined the random graph, coloring axioms and degree-limited pseudoexpectation.','Checked the published 2025 lower bound instead of repeating obsolete open status.','Left the precision of any residual threshold question unresolved rather than inventing one.'],checked_sources=[r['url'] for r in refs]+['https://acm-stoc.org/stoc2025/toc.html'],state='improved_unfinished')

i='TCS-2621';_,c=card(i);refs=c['references'];refs[0]['locator']='COLT 2023: equations (1)–(3), Section 1.1 final open-question paragraph, Section 2.1 asymptotic conventions, and Theorem 3.1 read. The target is polynomial-time recovery of one component from a random start in a fourth-order overcomplete Gaussian model.'
refs.append(dict(id='tensor_pca2024',title='Sharp Analysis of Power Iteration for Tensor PCA',authors='Yuchen Wu, Kangjie Zhou',year=2024,url='https://jmlr.org/papers/v25/24-0006.html',pdf_url='https://jmlr.org/papers/volume25/24-0006/24-0006.pdf',locator='JMLR 25, published June 2024: abstract and equation (1) read. The positive polynomial-iteration result concerns a single planted rank-one tensor plus independent Gaussian noise, not the sum of many Gaussian rank-one components in the original question.'))
issue='The informal positive conjecture says “correctly learn” in polynomial time but does not prescribe the recovery error, its dependence on d and k, or a uniform polynomial iteration bound across all sequences d≪k≪d². A precise stopping/output convention is also needed if success means a returned iterate rather than visiting a good iterate. The normalized iteration and rank regime are recoverable, but an exact numerical error target or a polynomial-in-accuracy claim must not be invented.'
save(i,dict(title='Does random-start tensor power iteration eventually recover a component?',formal='For a fourth-order tensor T=Σ_{i=1}^k aᵢ^{⊗4} with independent aᵢ∼N(0,I_d/d), does tensor power iteration from an independent random direction recover one of the component directions, up to sign, within polynomially many iterations throughout the overcomplete regime d≪k≪d²? The source conjectures positive recovery despite its polynomial lower bound on convergence time, but does not quantify the required recovery error or all dependencies of the polynomial bound.',definitions='The input consists of the entries of the symmetric real tensor T∈(ℝᵈ)^{⊗4}; the individual aᵢ are hidden. Each aᵢ has independent coordinates of mean zero and variance 1/d, and all components are mutually independent. Let x₀ be uniform on the Euclidean sphere of radius √d and independent of these components. Define zₜ=T(I,xₜ₋₁,xₜ₋₁,xₜ₋₁)=Σᵢ⟨aᵢ,xₜ₋₁⟩³aᵢ and xₜ=√d·zₜ/‖zₜ‖₂. On the null event of a zero denominator, declare the run failed. No new tensor samples or independent noise are introduced between iterations. The same dynamics is normalized gradient ascent for S(x)=Σᵢ⟨aᵢ,x⟩⁴. The regime means integer sequences k=k(d) with k/d→∞ and k/d²→0 as d→∞; it is not restricted to k=d^c for a fixed exponent c. Directional error can be measured by min_{i,s∈{−1,+1}}‖xₜ/√d−s aᵢ/‖aᵢ‖₂‖₂, but the source does not specify its required size. Probability is over both the tensor components and the independent initial direction. The paper studies iteration counts with exact real arithmetic, not bit complexity of Gaussian input encodings. The target is recovery of one component; recovery of the entire decomposition is a different task.',question_type='yes_no',answer_criterion='A precise completion must give a recovery tolerance, success guarantee, stopping/output rule and the permitted parameter dependence of a polynomial iteration bound, then prove or refute that bound for the stated random model. A theorem that only shows the objective increasing, assumes an initially correlated component, or analyzes a planted single-spike tensor with Gaussian noise does not settle the source question.',context_blocks=[b('Overcomplete means more components than dimensions','The tensor combines k hidden directions in ℝᵈ with k much larger than d. Randomness is imposed on the entire collection of directions, rather than on additive observation noise.', 'primary'),b('Random initialization can lead to a long delay','For d^{3/2}≪k≪d², Theorem 3.1 proves that all iterates up to T=o(k^{2/3}/(d(log k)^{1/3})) have vanishing normalized correlation with every component. For fixed k comparable to d^c with 3/2<c<2, this entails a polynomial delay.', 'primary'),b('A polynomial delay does not rule out polynomial recovery','The authors’ numerical evidence motivates eventual polynomial-time success. Their lower bound disproves an overly rapid convergence expectation, not that later polynomially many iterations can work.', 'primary'),b('The later tensor PCA theorem concerns different randomness','The 2024 paper gives a sharp positive analysis for one planted spike plus a tensor of independent Gaussian noise entries. That is not the overcomplete sum in this question, even though both use randomly initialized power iteration.', 'tensor_pca2024'),b('What still needs specification',issue)],why='Would distinguish a long initial transient from a genuine algorithmic failure in a basic nonconvex tensor method, under a standard random overcomplete model.',references=refs,progress=[dict(date='2023',text='A polynomial lower bound on random-start convergence is proved; the authors conjecture eventual polynomial-time recovery when k=o(d²).',citation='primary'),dict(date='2024-06',text='The same authors analyze polynomially many iterations for tensor PCA, a different single-spike-plus-noise model.',citation='tensor_pca2024')],status='source_open',status_note='The original model, recurrence, rank convention and lower-bound theorem were read and compared with the June 2024 JMLR result. Author research listings and subsequent-result searches through 12 September 2026 did not yield a resolution of this overcomplete-model question. Its requested quantitative recovery guarantee remains informal.',model_self_contained=False,requires_context=True,statement_review=dict(reviewed_on=DATE,status='needs_specification',remaining_issue=issue,notes=['Recovered the fourth-order Gaussian model and exact recurrence while preserving missing recovery guarantees.']),importance=imp(c,'A basic convergence question for an inexpensive iterative algorithm on random overcomplete tensor decompositions.'),review_note='Recovered the precise tensor order, variance, initialization, normalized update and little-o regime. Distinguished one-component direction recovery from exact decomposition and from the later tensor PCA result.',working_summary=sm(['The input tensor is a sum of many independent Gaussian rank-one fourth-order tensors.','Power iteration repeatedly contracts that tensor with its current direction and normalizes the result.','The source asks whether an independent random start eventually finds a hidden component in polynomially many iterations when d≪k≪d².','The proved polynomial delay and the later single-spike tensor PCA theorem do not settle that question.','A quantitative recovery error and uniform time/output guarantee still need to be specified.'],['primary','tensor_pca2024'])),notes=['Restored the exact fourth-order overcomplete model and normalized tensor-power recurrence.','Recovered the source little-o rank regime and polynomial-delay bound.','Separated hidden-component recovery from single-spike tensor PCA.','Preserved the unquantified accuracy and polynomial-time dependencies.'],checked_sources=[r['url'] for r in refs]+['https://kangjie287.github.io/research.html','https://wuyc0114.github.io/research.html'],state='improved_unfinished')
